PRAGMA application_id=1296978481;
PRAGMA user_version=0;
CREATE TABLE accounts(id TEXT PRIMARY KEY, issuer TEXT NOT NULL, subject TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN('active','blocked')), pilot_admitted INTEGER NOT NULL CHECK(pilot_admitted IN(0,1)), revision INTEGER NOT NULL DEFAULT 1, UNIQUE(issuer,subject)) STRICT;
CREATE TABLE action_leases(id TEXT PRIMARY KEY, project_id TEXT NOT NULL, turn_id TEXT NOT NULL, action_id TEXT NOT NULL, action_digest TEXT NOT NULL, fence_json TEXT NOT NULL CHECK(json_valid(fence_json)), expires_at INTEGER NOT NULL, UNIQUE(project_id,turn_id,action_id), FOREIGN KEY(project_id,turn_id) REFERENCES turns(project_id,id)) STRICT;
CREATE TABLE agents(id TEXT PRIMARY KEY, owner_account_id TEXT NOT NULL REFERENCES accounts(id), home_node_id TEXT NOT NULL, name TEXT NOT NULL, revision INTEGER NOT NULL DEFAULT 1, FOREIGN KEY(home_node_id,owner_account_id) REFERENCES nodes(id,owner_account_id)) STRICT;
CREATE TABLE authority_events(cursor INTEGER PRIMARY KEY AUTOINCREMENT, project_id TEXT NOT NULL REFERENCES projects(id), kind TEXT NOT NULL, subject_id TEXT NOT NULL, revision INTEGER NOT NULL, created_at INTEGER NOT NULL) STRICT;
CREATE TABLE command_receipts(project_id TEXT NOT NULL REFERENCES projects(id), actor_account_id TEXT NOT NULL REFERENCES accounts(id), request_id TEXT NOT NULL, digest TEXT NOT NULL, result_json TEXT NOT NULL CHECK(json_valid(result_json)), PRIMARY KEY(project_id,actor_account_id,request_id)) STRICT;
CREATE TABLE host_bindings(host TEXT PRIMARY KEY, project_id TEXT NOT NULL UNIQUE REFERENCES projects(id), generation INTEGER NOT NULL DEFAULT 1, active INTEGER NOT NULL DEFAULT 1 CHECK(active IN(0,1))) STRICT;
CREATE TABLE hub_migrations(version INTEGER PRIMARY KEY, checksum TEXT NOT NULL) STRICT;
CREATE TABLE hub_state(id INTEGER PRIMARY KEY CHECK(id=1), authority_generation TEXT NOT NULL, state TEXT NOT NULL CHECK(state IN('active','recovery')), revision INTEGER NOT NULL DEFAULT 1) STRICT;
CREATE TABLE invitations(id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id), issuer_account_id TEXT NOT NULL, issuer_revision INTEGER NOT NULL, mailbox_digest TEXT NOT NULL, target_account_id TEXT REFERENCES accounts(id), token_digest TEXT NOT NULL UNIQUE, role TEXT NOT NULL CHECK(role IN('admin','member','viewer')), expires_at INTEGER NOT NULL, state TEXT NOT NULL DEFAULT 'pending' CHECK(state IN('pending','accepted','revoked','held')), accepted_by TEXT REFERENCES accounts(id), authority_generation TEXT NOT NULL, revision INTEGER NOT NULL DEFAULT 1,
 FOREIGN KEY(project_id,issuer_account_id) REFERENCES memberships(project_id,account_id), UNIQUE(project_id,id)) STRICT;
CREATE TABLE memberships(project_id TEXT NOT NULL REFERENCES projects(id), account_id TEXT NOT NULL REFERENCES accounts(id), role TEXT NOT NULL CHECK(role IN('owner','admin','member','viewer')), status TEXT NOT NULL DEFAULT 'active' CHECK(status IN('active','revoked')), revision INTEGER NOT NULL DEFAULT 1, CHECK(role!='owner' OR status='active'), PRIMARY KEY(project_id,account_id), UNIQUE(project_id,account_id,role)) STRICT;
CREATE TABLE messages(id TEXT PRIMARY KEY, project_id TEXT NOT NULL, section_id TEXT NOT NULL, requester_account_id TEXT NOT NULL, text TEXT NOT NULL, created_at INTEGER NOT NULL, UNIQUE(project_id,id), FOREIGN KEY(project_id,section_id) REFERENCES sections(project_id,id), FOREIGN KEY(project_id,requester_account_id) REFERENCES memberships(project_id,account_id)) STRICT;
CREATE TABLE node_results(project_id TEXT NOT NULL, turn_id TEXT NOT NULL, sequence INTEGER NOT NULL, event_id TEXT NOT NULL, digest TEXT NOT NULL, frame_json TEXT NOT NULL CHECK(json_valid(frame_json)), PRIMARY KEY(project_id,turn_id,sequence), UNIQUE(project_id,event_id), FOREIGN KEY(project_id,turn_id) REFERENCES turns(project_id,id)) STRICT;
CREATE TABLE nodes(id TEXT PRIMARY KEY, owner_account_id TEXT NOT NULL REFERENCES accounts(id), installation_id TEXT NOT NULL UNIQUE, signing_public_key TEXT NOT NULL, encryption_public_key TEXT NOT NULL, capabilities_json TEXT NOT NULL CHECK(json_valid(capabilities_json)), generation INTEGER NOT NULL DEFAULT 1, key_revision INTEGER NOT NULL DEFAULT 1, connection_generation INTEGER NOT NULL DEFAULT 0, status TEXT NOT NULL DEFAULT 'offline' CHECK(status IN('offline','ready','revoked')), last_seen INTEGER, UNIQUE(id,owner_account_id)) STRICT;
CREATE TABLE outbox(event_id TEXT PRIMARY KEY, project_id TEXT NOT NULL, section_id TEXT NOT NULL, participation_id TEXT NOT NULL, node_id TEXT NOT NULL REFERENCES nodes(id), turn_id TEXT, kind TEXT NOT NULL, fence_json TEXT NOT NULL CHECK(json_valid(fence_json)), frame_json TEXT NOT NULL CHECK(json_valid(frame_json)), expires_at INTEGER NOT NULL, acked INTEGER NOT NULL DEFAULT 0 CHECK(acked IN(0,1)), FOREIGN KEY(project_id,section_id) REFERENCES sections(project_id,id), FOREIGN KEY(project_id,participation_id) REFERENCES participations(project_id,id), FOREIGN KEY(project_id,turn_id) REFERENCES turns(project_id,id)) STRICT;
CREATE TABLE participation_sections(project_id TEXT NOT NULL, participation_id TEXT NOT NULL, section_id TEXT NOT NULL, PRIMARY KEY(project_id,participation_id,section_id), FOREIGN KEY(project_id,participation_id) REFERENCES participations(project_id,id), FOREIGN KEY(project_id,section_id) REFERENCES sections(project_id,id)) STRICT;
CREATE TABLE participations(id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id), agent_id TEXT NOT NULL REFERENCES agents(id), revision INTEGER NOT NULL DEFAULT 1, owner_membership_revision INTEGER NOT NULL, owner_consent_revision INTEGER, project_consent_revision INTEGER, policy_json TEXT NOT NULL CHECK(json_valid(policy_json)), state TEXT NOT NULL DEFAULT 'proposed' CHECK(state IN('proposed','active','revoked')), UNIQUE(project_id,id), UNIQUE(project_id,agent_id)) STRICT;
CREATE TABLE projects(id TEXT PRIMARY KEY, owner_account_id TEXT NOT NULL REFERENCES accounts(id), owner_role TEXT NOT NULL DEFAULT 'owner' CHECK(owner_role='owner'), slug TEXT NOT NULL UNIQUE, name TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'active' CHECK(status IN('active','deleted')), revision INTEGER NOT NULL DEFAULT 1,
 FOREIGN KEY(id,owner_account_id,owner_role) REFERENCES memberships(project_id,account_id,role) DEFERRABLE INITIALLY DEFERRED) STRICT;
CREATE TABLE sections(id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id), name TEXT NOT NULL, archived INTEGER NOT NULL DEFAULT 0 CHECK(archived IN(0,1)), revision INTEGER NOT NULL DEFAULT 1, UNIQUE(project_id,id)) STRICT;
CREATE TABLE turns(id TEXT PRIMARY KEY, project_id TEXT NOT NULL, section_id TEXT NOT NULL, participation_id TEXT NOT NULL, message_id TEXT NOT NULL, requester_account_id TEXT NOT NULL, payer_account_id TEXT NOT NULL REFERENCES accounts(id), payer_binding_ref TEXT NOT NULL, node_id TEXT NOT NULL REFERENCES nodes(id), command_digest TEXT NOT NULL, fence_json TEXT NOT NULL CHECK(json_valid(fence_json)), request_json TEXT NOT NULL CHECK(json_valid(request_json)), state TEXT NOT NULL CHECK(state IN('pending','admitted','done','failed','unknown','revoked')), result_sequence INTEGER NOT NULL DEFAULT 0, UNIQUE(project_id,id), FOREIGN KEY(project_id,section_id) REFERENCES sections(project_id,id), FOREIGN KEY(project_id,participation_id) REFERENCES participations(project_id,id), FOREIGN KEY(project_id,message_id) REFERENCES messages(project_id,id), FOREIGN KEY(project_id,requester_account_id) REFERENCES memberships(project_id,account_id)) STRICT;
CREATE INDEX authority_project ON authority_events(project_id,cursor);
CREATE UNIQUE INDEX one_project_owner ON memberships(project_id) WHERE role='owner';
CREATE INDEX outbox_node ON outbox(node_id,acked);
CREATE INDEX participation_agent ON participations(agent_id);
CREATE TRIGGER account_identity_immutable BEFORE UPDATE OF id,issuer,subject ON accounts BEGIN SELECT RAISE(ABORT,'account identity is immutable'); END;
CREATE TRIGGER agent_home_immutable BEFORE UPDATE OF id,owner_account_id,home_node_id ON agents BEGIN SELECT RAISE(ABORT,'agent home is immutable'); END;
CREATE TRIGGER node_owner_immutable BEFORE UPDATE OF id,owner_account_id,installation_id ON nodes BEGIN SELECT RAISE(ABORT,'node owner is immutable'); END;
CREATE TRIGGER owner_stays_active BEFORE UPDATE OF status ON memberships WHEN NEW.role='owner' AND NEW.status!='active' BEGIN SELECT RAISE(ABORT,'owner must remain active'); END;
CREATE TRIGGER participation_identity_immutable BEFORE UPDATE OF id,project_id,agent_id ON participations BEGIN SELECT RAISE(ABORT,'participation identity is immutable'); END;
CREATE TRIGGER project_identity_immutable BEFORE UPDATE OF id,slug ON projects BEGIN SELECT RAISE(ABORT,'project identity is immutable'); END;
CREATE TRIGGER project_tombstone BEFORE DELETE ON projects BEGIN SELECT RAISE(ABORT,'project slugs are tombstoned'); END;
CREATE TRIGGER section_project_immutable BEFORE UPDATE OF id,project_id ON sections BEGIN SELECT RAISE(ABORT,'section project is immutable'); END;
CREATE TRIGGER turn_intent_immutable BEFORE UPDATE OF id,project_id,section_id,participation_id,message_id,requester_account_id,payer_account_id,payer_binding_ref,node_id,command_digest,fence_json,request_json ON turns BEGIN SELECT RAISE(ABORT,'turn intent is immutable'); END;
